CREATE OR REPLACE FUNCTION public.app_current_role()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  cur_uid TEXT;
  r TEXT;
  v_acting uuid;
  v_tenant uuid;
BEGIN
